import type { ItemInput } from './items.schema.ts';
import type { ExpenseItem, NewItem } from './items.types.ts';

/**
 * Items as they are stored after a person saved the list. An item keeps its "generated by AI" mark only when it
 * is the same item (its id) and nothing was changed in it; every other item is the person's own.
 * The mark is decided here and not taken from the client, so it cannot be set by hand.
 */
export function withSources(input: ItemInput[], existing: ExpenseItem[]): NewItem[] {
  const byId = new Map(existing.map((item) => [item.id, item]));
  return input.map(({ id, name, price, quantity }) => {
    const before = id ? byId.get(id) : undefined;
    const untouched =
      before?.source === 'ai' &&
      before.name === name &&
      before.price === price &&
      before.quantity === quantity;
    return { name, price, quantity, source: untouched ? 'ai' : 'manual' };
  });
}
